#if UNITY_EDITOR
using TMPro;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.SceneManagement;
using UnityEngine.UI;

namespace PongWall.Editor
{
    /// <summary>
    /// Builds (or refreshes) the Pong Wall interface.
    ///
    /// Design notes:
    ///  - The project ships no UI art, so every shape comes from sprites generated by
    ///    <see cref="UiSpriteGenerator"/>. This script runs that generator first, which
    ///    means a fresh clone can always produce the full look with one menu click.
    ///  - Everything is 9-sliced and white so a single palette tints it all.
    ///  - The script is idempotent: existing objects are reused, never duplicated.
    /// </summary>
    public static class PongWallUiSetup
    {
        private const string MenuPath = "PongWall/Setup UI";
        private const string ScenePath = "Assets/Scenes/SampleScene.unity";

        private static readonly string[] DrawOrder =
        {
            "UiBackdrop",
            "BottomFade",
            "BackdropGlow",
            "GameplayPanel",
            "HudBar",
            "ExtraBallButtons",
            "PauseButton",
            "PausePanel",
            "GameOverPanel"
        };

        [MenuItem(MenuPath + " %#u", false, 0)]
        public static void SetupUi()
        {
            SetupInternal();
        }

        /// <summary>Entry point for -executeMethod command line calls.</summary>
        public static void SetupUiFromBatch()
        {
            SetupInternal();
            EditorSceneManager.SaveOpenScenes();
            AssetDatabase.SaveAssets();
        }

        private static void SetupInternal()
        {
            UiSpriteGenerator.GenerateAll();

            var scene = SceneManager.GetActiveScene();
            if (scene.name != "SampleScene")
                scene = EditorSceneManager.OpenScene(ScenePath);

            var canvas = Object.FindFirstObjectByType<Canvas>();
            if (canvas == null)
            {
                Debug.LogError("Canvas not found in scene.");
                return;
            }

            var root = canvas.transform as RectTransform;

            BuildBackdrop(root);
            var hudScore = BuildHud(root);
            BuildExtraBallControls(root);
            BuildPause(root);
            BuildGameOver(root, hudScore);

            ApplyDrawOrder(root);
            EditorSceneManager.MarkSceneDirty(scene);
            Debug.Log("Pong Wall UI setup complete.");
        }

        // ============================================================== backdrop

        private static void BuildBackdrop(RectTransform canvas)
        {
            var backdrop = GetOrCreateRect(canvas, "UiBackdrop");
            Stretch(backdrop);
            var backdropImage = EnsureImage(backdrop);
            backdropImage.sprite = UiTheme.Solid;
            backdropImage.type = Image.Type.Simple;
            backdropImage.color = UiTheme.BackgroundBottom;
            backdropImage.raycastTarget = false;

            var glow = GetOrCreateRect(canvas, "BackdropGlow");
            glow.anchorMin = glow.anchorMax = new Vector2(0.5f, 0.5f);
            glow.pivot = new Vector2(0.5f, 0.5f);
            glow.sizeDelta = new Vector2(2900f, 2100f);
            glow.anchoredPosition = new Vector2(0f, 90f);
            var glowImage = EnsureImage(glow);
            glowImage.sprite = UiTheme.Glow;
            glowImage.type = Image.Type.Simple;
            glowImage.color = UiTheme.WithAlpha(UiTheme.Halo, 0.42f);
            glowImage.raycastTarget = false;

            var fade = GetOrCreateRect(canvas, "BottomFade");
            Stretch(fade);
            var fadeImage = EnsureImage(fade);
            fadeImage.sprite = UiTheme.FadeUp;
            fadeImage.type = Image.Type.Simple;
            fadeImage.color = UiTheme.BackgroundBottom;
            fadeImage.raycastTarget = false;
        }

        // =================================================================== HUD

        /// <summary>Returns the score label so the game over panel can be themed too.</summary>
        private static TextMeshProUGUI BuildHud(RectTransform canvas)
        {
            var bar = GetOrCreateRect(canvas, "HudBar");
            bar.anchorMin = bar.anchorMax = new Vector2(0f, 1f);
            bar.pivot = new Vector2(0f, 1f);
            bar.sizeDelta = new Vector2(1080f, 180f);
            bar.anchoredPosition = new Vector2(48f, -44f);
            var barImage = EnsureImage(bar);
            barImage.sprite = UiTheme.Pill;
            barImage.type = Image.Type.Sliced;
            barImage.color = UiTheme.SurfaceTranslucent;
            barImage.raycastTarget = false;

            var scoreCaption = CreateText(bar, "ScoreCaption", "SCORE");
            TopLeft(scoreCaption.rectTransform, new Vector2(58f, -30f), new Vector2(320f, 36f));
            StyleCaption(scoreCaption, UiTheme.TextFaint);

            // Reuse the score label that already ships in the scene: ScoreView is bound to it.
            // Search order matters: after the first run the label lives inside the bar itself.
            var scoreLabel = FindDescendant(bar, "ScoreText (TMP)")
                             ?? canvas.Find("ScoreText (TMP)")?.GetComponent<TextMeshProUGUI>()
                             ?? CreateText(bar, "ScoreText (TMP)", "0");

            scoreLabel.transform.SetParent(bar, false);
            var scoreRect = scoreLabel.rectTransform;
            scoreRect.anchorMin = scoreRect.anchorMax = new Vector2(0f, 0f);
            scoreRect.pivot = new Vector2(0f, 0f);
            scoreRect.sizeDelta = new Vector2(420f, 104f);
            scoreRect.anchoredPosition = new Vector2(52f, 14f);
            scoreLabel.fontSize = UiTheme.BigNumberSize;
            scoreLabel.fontStyle = FontStyles.Bold;
            scoreLabel.alignment = TextAlignmentOptions.Left;
            scoreLabel.color = UiTheme.TextPrimary;
            scoreLabel.raycastTarget = false;

            var divider = CreateImage(bar, "HudDivider", UiTheme.Solid, UiTheme.Hairline);
            divider.rectTransform.anchorMin = divider.rectTransform.anchorMax = new Vector2(0f, 0.5f);
            divider.rectTransform.pivot = new Vector2(0.5f, 0.5f);
            divider.rectTransform.sizeDelta = new Vector2(2f, 108f);
            divider.rectTransform.anchoredPosition = new Vector2(506f, 0f);

            var bestCaption = CreateText(bar, "BestCaption", "BEST");
            TopLeft(bestCaption.rectTransform, new Vector2(566f, -30f), new Vector2(240f, 36f));
            StyleCaption(bestCaption, UiTheme.TextFaint);

            var bestLabel = CreateText(bar, "BestScoreText", "Best: 0");
            var bestRect = bestLabel.rectTransform;
            bestRect.anchorMin = bestRect.anchorMax = new Vector2(0f, 0f);
            bestRect.pivot = new Vector2(0f, 0f);
            bestRect.sizeDelta = new Vector2(420f, 80f);
            bestRect.anchoredPosition = new Vector2(562f, 30f);
            bestLabel.fontSize = UiTheme.SubNumberSize;
            bestLabel.fontStyle = FontStyles.Bold;
            bestLabel.alignment = TextAlignmentOptions.Left;
            bestLabel.color = UiTheme.Gold;
            bestLabel.raycastTarget = false;

            var bestView = bestLabel.gameObject.GetComponent<BestScoreView>();
            if (bestView == null)
                bestView = bestLabel.gameObject.AddComponent<BestScoreView>();

            var bestSerialized = new SerializedObject(bestView);
            bestSerialized.FindProperty("_label").objectReferenceValue = bestLabel;
            bestSerialized.ApplyModifiedPropertiesWithoutUndo();

            return scoreLabel;
        }

        // ======================================================= extra ball tools

        private static void BuildExtraBallControls(RectTransform canvas)
        {
            RectTransform container;
            var existing = canvas.Find("ExtraBallButtons");
            if (existing == null)
            {
                container = GetOrCreateRect(canvas, "ExtraBallButtons");
                container.anchorMin = container.anchorMax = new Vector2(1f, 0f);
                container.pivot = new Vector2(1f, 0f);
                container.sizeDelta = new Vector2(560f, 104f);
            }
            else
            {
                container = existing as RectTransform;
                container.SetParent(canvas, false);
            }

            container.anchorMin = container.anchorMax = new Vector2(1f, 0f);
            container.pivot = new Vector2(1f, 0f);
            container.sizeDelta = new Vector2(560f, 104f);
            container.anchoredPosition = new Vector2(-48f, 44f);

            var containerImage = EnsureImage(container);
            containerImage.sprite = UiTheme.Pill;
            containerImage.type = Image.Type.Sliced;
            containerImage.color = UiTheme.SurfaceTranslucent;
            containerImage.raycastTarget = false;

            var spawn = StyleChildButton(container, "SpawnExtraBallButton", "+ BALL", UiButtonKind.Primary);
            spawn.anchorMin = spawn.anchorMax = new Vector2(0f, 0.5f);
            spawn.pivot = new Vector2(0f, 0.5f);
            spawn.sizeDelta = new Vector2(238f, 68f);
            spawn.anchoredPosition = new Vector2(30f, 0f);

            var remove = StyleChildButton(container, "RemoveExtraBallButton", "- BALL", UiButtonKind.Secondary);
            remove.anchorMin = remove.anchorMax = new Vector2(1f, 0.5f);
            remove.pivot = new Vector2(1f, 0.5f);
            remove.sizeDelta = new Vector2(238f, 68f);
            remove.anchoredPosition = new Vector2(-30f, 0f);
        }

        // =============================================================== pause

        private static void BuildPause(RectTransform canvas)
        {
            var panel = GetOrCreateRect(canvas, "PausePanel");
            Stretch(panel);

            var panelImage = EnsureImage(panel);
            panelImage.sprite = UiTheme.Solid;
            panelImage.type = Image.Type.Simple;
            panelImage.color = UiTheme.Scrim;
            panelImage.raycastTarget = true;

            var group = panel.GetComponent<CanvasGroup>();
            if (group == null)
                group = panel.gameObject.AddComponent<CanvasGroup>();
            group.alpha = 0f;
            group.interactable = false;
            group.blocksRaycasts = false;

            var card = CreateCard(panel, "PauseCard", new Vector2(1080f, 720f));

            var title = CreateText(card, "PauseTitle", "PAUSED");
            TopCenter(title.rectTransform, new Vector2(0f, -74f), new Vector2(900f, 122f));
            StyleHero(title, UiTheme.TextPrimary);

            var divider = CreateImage(card, "PauseDivider", UiTheme.Solid, UiTheme.Hairline);
            divider.rectTransform.anchorMin = divider.rectTransform.anchorMax = new Vector2(0.5f, 1f);
            divider.rectTransform.pivot = new Vector2(0.5f, 1f);
            divider.rectTransform.sizeDelta = new Vector2(560f, 2f);
            divider.rectTransform.anchoredPosition = new Vector2(0f, -232f);

            var continueRect = CreateButton(card, "PauseContinueButton", "PLAY", UiButtonKind.Primary, UiTheme.ButtonSize);
            continueRect.anchoredPosition = new Vector2(0f, 24f);

            var restartRect = CreateButton(card, "PauseRestartButton", "RESTART", UiButtonKind.Secondary, UiTheme.ButtonSize);
            restartRect.anchoredPosition = new Vector2(0f, -104f);

            var hint = CreateText(card, "PauseHint", "ESC  -  RESUME");
            BottomCenter(hint.rectTransform, new Vector2(0f, 78f), new Vector2(800f, 46f));
            StyleCaption(hint, UiTheme.TextFaint);

            var toggle = BuildPauseToggleButton(canvas);

            var pauseView = panel.gameObject.GetComponent<PauseView>();
            if (pauseView == null)
                pauseView = panel.gameObject.AddComponent<PauseView>();

            var serialized = new SerializedObject(pauseView);
            serialized.FindProperty("_panel").objectReferenceValue = group;
            serialized.FindProperty("_toggleButton").objectReferenceValue = toggle;
            serialized.FindProperty("_continueButton").objectReferenceValue = ButtonOf(continueRect);
            serialized.FindProperty("_restartButton").objectReferenceValue = ButtonOf(restartRect);
            serialized.ApplyModifiedPropertiesWithoutUndo();
        }

        private static Button BuildPauseToggleButton(RectTransform canvas)
        {
            var host = GetOrCreateRect(canvas, "PauseButton");
            host.anchorMin = host.anchorMax = new Vector2(1f, 1f);
            host.pivot = new Vector2(1f, 1f);
            host.sizeDelta = new Vector2(124f, 124f);
            host.anchoredPosition = new Vector2(-48f, -44f);

            var image = EnsureImage(host);
            image.sprite = UiTheme.Disc;
            image.type = Image.Type.Sliced;
            image.color = UiTheme.SurfaceTranslucent;
            image.raycastTarget = true;

            var button = host.gameObject.GetComponent<Button>();
            if (button == null)
                button = host.gameObject.AddComponent<Button>();
            button.targetGraphic = image;
            AddFeedback(host.gameObject);

            var colors = button.colors;
            colors.normalColor = Color.white;
            colors.highlightedColor = new Color(1f, 1f, 1f, 0.14f);
            colors.pressedColor = new Color(1f, 1f, 1f, 0.05f);
            colors.selectedColor = colors.highlightedColor;
            colors.disabledColor = new Color(1f, 1f, 1f, 0.25f);
            colors.fadeDuration = 0.12f;
            button.colors = colors;

            CreateBar(host, "PauseBarLeft", -18f);
            CreateBar(host, "PauseBarRight", 18f);
            return button;
        }

        private static void CreateBar(Transform parent, string name, float xOffset)
        {
            var bar = CreateImage(parent, name, UiTheme.Solid, UiTheme.TextPrimary);
            bar.rectTransform.anchorMin = bar.rectTransform.anchorMax = new Vector2(0.5f, 0.5f);
            bar.rectTransform.pivot = new Vector2(0.5f, 0.5f);
            bar.rectTransform.sizeDelta = new Vector2(18f, 48f);
            bar.rectTransform.anchoredPosition = new Vector2(xOffset, 0f);
        }

        // ============================================================ game over

        private static void BuildGameOver(RectTransform canvas, TextMeshProUGUI hudScore)
        {
            var existing = canvas.Find("GameOverPanel");
            if (existing == null)
            {
                Debug.LogWarning("GameOverPanel not found - skipping game over UI rebuild.");
                return;
            }

            // Grab the pre-existing children before we restructure the hierarchy.
            var scoreLabel = FindDescendant(existing, "ScoreText (TMP)");
            var restartButtonObject = existing.Find("RestartButton");

            existing.SetParent(canvas, false);
            var panel = existing as RectTransform;
            Stretch(panel);

            var panelImage = EnsureImage(panel);
            panelImage.sprite = UiTheme.Solid;
            panelImage.type = Image.Type.Simple;
            panelImage.color = UiTheme.Scrim;
            panelImage.raycastTarget = true;

            var group = panel.GetComponent<CanvasGroup>();
            if (group == null)
                group = panel.gameObject.AddComponent<CanvasGroup>();

            var card = CreateCard(panel, "GameOverCard", UiTheme.CardSize);

            var title = CreateText(card, "GameOverTitle", "GAME OVER");
            TopCenter(title.rectTransform, new Vector2(0f, -72f), new Vector2(1000f, 124f));
            StyleHero(title, UiTheme.TextPrimary);

            var divider = CreateImage(card, "GameOverDivider", UiTheme.Solid, UiTheme.Hairline);
            divider.rectTransform.anchorMin = divider.rectTransform.anchorMax = new Vector2(0.5f, 1f);
            divider.rectTransform.pivot = new Vector2(0.5f, 1f);
            divider.rectTransform.sizeDelta = new Vector2(620f, 2f);
            divider.rectTransform.anchoredPosition = new Vector2(0f, -222f);

            // The scene shipped a second ScoreView on the game over score label, which makes
            // the ScoreView binding ambiguous. Drop it and keep only the HUD one.
            if (scoreLabel != null)
            {
                var strayView = scoreLabel.gameObject.GetComponent<ScoreView>();
                if (strayView != null)
                    Object.DestroyImmediate(strayView, true);

                scoreLabel.transform.SetParent(card, false);
                Centered(scoreLabel.rectTransform, new Vector2(0f, 74f), new Vector2(900f, 148f));
                scoreLabel.fontSize = UiTheme.HeroSize;
                scoreLabel.fontStyle = FontStyles.Bold;
                scoreLabel.alignment = TextAlignmentOptions.Center;
                scoreLabel.color = UiTheme.TextPrimary;
                scoreLabel.raycastTarget = false;
            }

            var bestLabel = CreateText(card, "GameOverBestScoreText", "Best: 0");
            Centered(bestLabel.rectTransform, new Vector2(0f, -42f), new Vector2(760f, 62f));
            bestLabel.fontSize = UiTheme.SubNumberSize;
            bestLabel.fontStyle = FontStyles.Bold;
            bestLabel.alignment = TextAlignmentOptions.Center;
            bestLabel.color = UiTheme.Gold;
            bestLabel.raycastTarget = false;

            RectTransform restartRect;
            if (restartButtonObject != null)
            {
                restartButtonObject.SetParent(card, false);
                var styled = StyleExistingButton(restartButtonObject, "PLAY AGAIN", UiButtonKind.Primary);
                restartRect = styled.transform as RectTransform;
                restartRect.localScale = Vector3.one;
            }
            else
            {
                restartRect = CreateButton(card, "RestartButton", "PLAY AGAIN", UiButtonKind.Primary, UiTheme.ButtonSize);
            }

            Centered(restartRect, new Vector2(0f, -212f), UiTheme.ButtonSize);

            // A pause control has no meaning after the run has ended. Remove the
            // dead button left by older builds and show the keyboard shortcut instead.
            var legacyPause = card.Find("GameOverPauseButton");
            if (legacyPause != null)
                Object.DestroyImmediate(legacyPause.gameObject, true);

            var hint = CreateText(card, "GameOverHint", "R / ENTER  -  RESTART");
            BottomCenter(hint.rectTransform, new Vector2(0f, 66f), new Vector2(800f, 44f));
            StyleCaption(hint, UiTheme.TextFaint);
            hint.alignment = TextAlignmentOptions.Center;

            var gameOverView = panel.gameObject.GetComponent<GameOverView>();
            if (gameOverView == null)
                gameOverView = panel.gameObject.AddComponent<GameOverView>();

            var serialized = new SerializedObject(gameOverView);
            serialized.FindProperty("_panel").objectReferenceValue = group;
            serialized.FindProperty("_bestScoreLabel").objectReferenceValue = bestLabel;

            if (scoreLabel != null)
                serialized.FindProperty("_finalScoreLabel").objectReferenceValue = scoreLabel;

            serialized.FindProperty("_restartButton").objectReferenceValue = ButtonOf(restartRect);
            serialized.FindProperty("_pauseButton").objectReferenceValue = null;
            serialized.ApplyModifiedPropertiesWithoutUndo();
        }

        // =============================================================== helpers

        private static RectTransform GetOrCreateRect(Transform parent, string name)
        {
            var existing = parent.Find(name);
            if (existing != null)
                return existing as RectTransform;

            var created = new GameObject(name, typeof(RectTransform));
            created.layer = parent.gameObject.layer;
            created.transform.SetParent(parent, false);
            return created.transform as RectTransform;
        }

        private static Image EnsureImage(RectTransform rect)
        {
            var canvasRenderer = rect.GetComponent<CanvasRenderer>();
            if (canvasRenderer == null)
                rect.gameObject.AddComponent<CanvasRenderer>();

            var image = rect.GetComponent<Image>();
            if (image == null)
                image = rect.gameObject.AddComponent<Image>();

            // The scene ships GameOverPanel with its Image disabled, so force it back on.
            image.enabled = true;
            image.type = Image.Type.Sliced;
            return image;
        }

        private static Image CreateImage(Transform parent, string name, Sprite sprite, Color color)
        {
            var rect = GetOrCreateRect(parent, name);
            var image = EnsureImage(rect);
            image.sprite = sprite;
            image.type = sprite != null && HasBorder(sprite) ? Image.Type.Sliced : Image.Type.Simple;
            image.color = color;
            image.raycastTarget = false;
            return image;
        }

        private static bool HasBorder(Sprite sprite)
        {
            return sprite != null && sprite.border.sqrMagnitude > 0f;
        }

        private static RectTransform CreateCard(Transform parent, string name, Vector2 size)
        {
            var card = GetOrCreateRect(parent, name);
            Centered(card, Vector2.zero, size);

            var image = EnsureImage(card);
            image.sprite = UiTheme.Card;
            image.type = Image.Type.Sliced;
            image.color = new Color(UiTheme.Surface.r, UiTheme.Surface.g, UiTheme.Surface.b, 0.98f);
            image.raycastTarget = true;
            return card;
        }

        private static TextMeshProUGUI CreateText(Transform parent, string name, string content)
        {
            var rect = GetOrCreateRect(parent, name);

            if (rect.GetComponent<CanvasRenderer>() == null)
                rect.gameObject.AddComponent<CanvasRenderer>();

            var label = rect.GetComponent<TextMeshProUGUI>();
            if (label == null)
                label = rect.gameObject.AddComponent<TextMeshProUGUI>();

            label.font = TMP_Settings.defaultFontAsset;
            label.text = content;
            label.raycastTarget = false;
            label.color = UiTheme.TextPrimary;
            return label;
        }

        private static void StyleCaption(TextMeshProUGUI label, Color color)
        {
            label.fontSize = UiTheme.CaptionSize;
            label.fontStyle = FontStyles.Normal;
            label.characterSpacing = UiTheme.CaptionSpacing;
            label.alignment = TextAlignmentOptions.Left;
            label.color = color;
        }

        private static void StyleHero(TextMeshProUGUI label, Color color)
        {
            label.fontSize = UiTheme.TitleSize;
            label.fontStyle = FontStyles.Bold;
            label.characterSpacing = UiTheme.TitleSpacing;
            label.alignment = TextAlignmentOptions.Center;
            label.color = color;

            var outline = label.GetComponent<Outline>();
            if (outline == null)
                outline = label.gameObject.AddComponent<Outline>();

            outline.effectColor = new Color(0f, 0f, 0f, 0.75f);
            outline.effectDistance = new Vector2(4f, -4f);
            outline.useGraphicAlpha = true;
        }

        private static RectTransform CreateButton(
            Transform parent,
            string name,
            string caption,
            UiButtonKind kind,
            Vector2 size)
        {
            var rect = GetOrCreateRect(parent, name);
            Centered(rect, Vector2.zero, size);

            var image = EnsureImage(rect);
            image.raycastTarget = true;

            var button = rect.gameObject.GetComponent<Button>();
            if (button == null)
                button = rect.gameObject.AddComponent<Button>();
            button.targetGraphic = image;

            AddFeedback(rect.gameObject);

            var label = FindDescendant(rect, "Text (TMP)") ?? FindChildLabel(rect);
            if (label == null)
                label = CreateText(rect, "Label", caption);
            Stretch(label.rectTransform);

            label.text = caption;
            label.fontSize = UiTheme.BodySize;
            label.fontStyle = FontStyles.Bold;
            label.characterSpacing = 6f;
            label.alignment = TextAlignmentOptions.Center;
            label.raycastTarget = false;

            UiTheme.StyleButton(button, kind);
            return rect;
        }

        private static RectTransform StyleChildButton(
            Transform parent,
            string name,
            string caption,
            UiButtonKind kind)
        {
            var existing = parent.Find(name);
            if (existing != null)
            {
                var styled = StyleExistingButton(existing, caption, kind);
                var rect = styled.transform as RectTransform;
                rect.localScale = Vector3.one;
                return rect;
            }

            return CreateButton(parent, name, caption, kind, new Vector2(238f, 68f));
        }

        private static Button ButtonOf(RectTransform rect)
        {
            return rect.GetComponent<Button>();
        }

        private static Button StyleExistingButton(Transform host, string caption, UiButtonKind kind)
        {
            var rect = host as RectTransform;
            var image = EnsureImage(rect);
            image.raycastTarget = true;

            var button = host.GetComponent<Button>();
            if (button == null)
                button = host.gameObject.AddComponent<Button>();
            button.targetGraphic = image;

            AddFeedback(host.gameObject);

            var label = FindChildLabel(host);
            if (label == null)
                label = CreateText(host, "Label", caption);
            Stretch(label.rectTransform);

            label.text = caption;
            label.fontSize = UiTheme.CaptionSize + 6f;
            label.fontStyle = FontStyles.Bold;
            label.characterSpacing = 4f;
            label.alignment = TextAlignmentOptions.Center;
            label.raycastTarget = false;

            UiTheme.StyleButton(button, kind);
            return button;
        }

        private static void AddFeedback(GameObject target)
        {
            if (target.GetComponent<UiButtonFeedback>() == null)
                target.AddComponent<UiButtonFeedback>();
        }

        private static TextMeshProUGUI FindChildLabel(Transform parent)
        {
            for (var index = 0; index < parent.childCount; index++)
            {
                var label = parent.GetChild(index).GetComponent<TextMeshProUGUI>();
                if (label != null)
                    return label;
            }

            return null;
        }

        private static TextMeshProUGUI FindDescendant(Transform root, string name)
        {
            var direct = root.Find(name);
            if (direct != null)
                return direct.GetComponent<TextMeshProUGUI>();

            for (var index = 0; index < root.childCount; index++)
            {
                var found = FindDescendant(root.GetChild(index), name);
                if (found != null)
                    return found;
            }

            return null;
        }

        private static void ApplyDrawOrder(RectTransform canvas)
        {
            for (var index = 0; index < DrawOrder.Length; index++)
            {
                var child = canvas.Find(DrawOrder[index]);
                child?.SetSiblingIndex(index);
            }
        }

        // ------------------------------------------------------------- rect utils

        private static void Stretch(RectTransform rect)
        {
            rect.anchorMin = Vector2.zero;
            rect.anchorMax = Vector2.one;
            rect.pivot = new Vector2(0.5f, 0.5f);
            rect.offsetMin = Vector2.zero;
            rect.offsetMax = Vector2.zero;
        }

        private static void Centered(RectTransform rect, Vector2 anchoredPosition, Vector2 size)
        {
            rect.anchorMin = rect.anchorMax = new Vector2(0.5f, 0.5f);
            rect.pivot = new Vector2(0.5f, 0.5f);
            rect.sizeDelta = size;
            rect.anchoredPosition = anchoredPosition;
        }

        private static void TopLeft(RectTransform rect, Vector2 anchoredPosition, Vector2 size)
        {
            rect.anchorMin = rect.anchorMax = new Vector2(0f, 1f);
            rect.pivot = new Vector2(0f, 1f);
            rect.sizeDelta = size;
            rect.anchoredPosition = anchoredPosition;
        }

        private static void TopCenter(RectTransform rect, Vector2 anchoredPosition, Vector2 size)
        {
            rect.anchorMin = rect.anchorMax = new Vector2(0.5f, 1f);
            rect.pivot = new Vector2(0.5f, 1f);
            rect.sizeDelta = size;
            rect.anchoredPosition = anchoredPosition;
        }

        private static void BottomCenter(RectTransform rect, Vector2 anchoredPosition, Vector2 size)
        {
            rect.anchorMin = rect.anchorMax = new Vector2(0.5f, 0f);
            rect.pivot = new Vector2(0.5f, 0f);
            rect.sizeDelta = size;
            rect.anchoredPosition = anchoredPosition;
        }
    }

    /// <summary>
    /// Builds the interface automatically the first time the sample scene is opened,
    /// so nobody has to go hunting for a menu item. Safe to re-run.
    /// </summary>
    [InitializeOnLoad]
    public static class PongWallUiAutoSetup
    {
        static PongWallUiAutoSetup()
        {
            EditorApplication.delayCall += TryAutoSetup;
        }

        private static void TryAutoSetup()
        {
            if (EditorApplication.isPlayingOrWillChangePlaymode)
                return;

            // Only ever touch the sample scene, never invent one.
            if (EditorSceneManager.GetActiveScene().name != "SampleScene")
                return;

            var canvas = Object.FindFirstObjectByType<Canvas>();
            if (canvas == null)
                return;

            // Marker object: already generated on a previous run.
            if (canvas.transform.Find("HudBar") != null)
                return;

            try
            {
                PongWallUiSetup.SetupUi();
                EditorSceneManager.SaveOpenScenes();
                Debug.Log("[PongWall] Interface generated and scene saved.");
            }
            catch (System.Exception exception)
            {
                // Never leave a half built scene behind on failure.
                Debug.LogError($"[PongWall] Interface generation failed: {exception}");
            }
        }
    }
}
#endif